div.script:

function _cc_processFile(inputId, displayId) {
    var files = gel(inputId).files;

    if ((!files || !files[0])) {

	} else {
		fileName = files[0].name;
		gel(displayId).textContent = " " + fileName;

		_cc_getBase64(files[0]).then(function(b64) {
			gel("b64-" + inputId).value = b64;
		});
	}



}

function _cc_getBase64(file) {
	return new Promise(function(resolve, reject) {

		var reader = new FileReader();
		reader.readAsDataURL(file);
		reader.onload = function() {
			var encoded = reader.result.replace(/^data:(.*;base64,)?/, '');
			if ((encoded.length % 4) > 0) {
				encoded += '='.repeat(4 - (encoded.length % 4));
			}
			resolve(encoded);
		};
		reader.onerror = function(error) {
			reject(error);
		};
	});
}
